272:     dt = Math.min(dt, .1);
273:     if (this.lureCd > 0) this.lureCd = Math.max(0, this.lureCd - dt);
274:     if (this.lureT > 0) this.lureT = Math.max(0, this.lureT - dt);
275:     const prevHour = this.hourIndex();
276:     this.nightT += dt;
277:     if (this.hourIndex() !== prevHour && this.nightT < NIGHT_SECONDS) {
278:       this.audio.hourBeep();
279:       this.events.onHour?.(this.hourIndex(), this.displayHour());
