326:   _beginBlackout() {
327:     this.blackout = true;
328:     this.blackoutT = 0;
329:     this.doors.left = this.doors.right = false;
330:     this.lights.left = this.lights.right = false;
331:     this.camOpen = false;
332:     this.lureT = 0;
333:     this.audio.powerDown();
334:     this.events.onPowerOut?.();
335:     // Foxy retreats in the dark; Freddy comes for you.
336:     if (this.foxy.running) { this.foxy.running = false; this.foxy.stage = 0; }
337:     for (const k in this.ai) { this.ai[k].atDoor = false; this.ai[k].index = Math.max(1, Math.min(2, this.ai[k].index)); }
338:     this.events.onClearCharacters?.();
