356:   _updateAI(dt) {
357:     if (this.startDelay > 0) { this.startDelay -= dt; return; }
358:     const pressure = this.timePressure();
359:     for (const name in this.ai) {
360:       const a = this.ai[name];
361:       // Freddy is shy — he freezes if you are watching his room.
362:       const watching = this.camOpen && this.camMatches(name, a) && name === 'freddy';
363:       if (a.cooldown > 0) { a.cooldown -= dt; continue; }
364: 
365:       if (a.atDoor) {
366:         if (this.doors[a.side]) {
367:           a.blockT -= dt;
368:           if (a.blockT <= 0) this._retreat(a);
369:           continue;
370:         }
371:         a.attackT -= dt;
372:         if (a.attackT <= 0) {
373:           this._kill(name);
374:           return;
375:         }
376:         // breathing at the door
377:         if (Math.random() < dt * .55) this.audio.breath(a.side === 'left' ? -.75 : .75);
378:         continue;
379:       }
380: 
381:       if (watching) continue;
382:       a.timer -= dt;
383:       if (a.timer <= 0) {
384:         a.timer = (a.interval / (.82 + pressure * .18)) * (.82 + Math.random() * .5);
385:         const chance = Math.min(.82, (a.level / 20) * pressure);
386:         if (Math.random() < chance) {
387:           this._advance(a);
388:         } else if (Math.random() < .13) {
389:           // restless shuffle
390:           this.audio.step(a.side === 'left' ? -.65 : .65, 1);
391:         }
392:       }
393:     }
394:   }
395: 
396:   camMatches(name, a) {
397:     return this.camForAI(name, a) === this.cam;
398:   }
399: 
400:   _advance(a) {
401:     a.index++;
402:     const pos = a.path[a.index];
403:     if (a.index >= a.path.length - 1) {
404:       a.atDoor = true;
405:       a.attackT = a.name === 'freddy' ? 10.5 : 7.2;
406:       a.blockT = .8;
407:       this.audio.knock(a.side === 'left' ? -.8 : .8);
408:       this.audio.step(a.side === 'left' ? -.7 : .7, 1.15);
409:       if (a.name === 'freddy') this.audio.laugh();
410:       this.events.onCorner?.(a.side, a.name);
411:       return;
412:     }
413:     if (pos === 'dining') this.audio.step(a.side === 'left' ? -.4 : .4, .85);
414:     else if (pos.includes('Hall')) this.audio.step(a.side === 'left' ? -.72 : .72, 1);
415:     else this.audio.servo(a.side === 'left' ? -.3 : .3);
416:     this.events.onMove?.(a.name, pos);
417:   }
418: 
419:   _retreat(a) {
420:     a.atDoor = false;
421:     a.index = Math.max(1, a.path.length - 3);
422:     a.cooldown = 9 + Math.random() * 7;
423:     a.timer = a.interval;
424:     a.blockT = 0;
425:     this.audio.thud({ gain: .18, pan: a.side === 'left' ? -.8 : .8 });
426:     this.audio.door(false, a.side === 'left' ? -.65 : .65);
427:     this.events.onRetreat?.(a.side, a.name);
428:   }
