462:       return;
463:     }
464:     f.timer -= dt;
465:     if (f.timer <= 0) {
466:       const chance = Math.min(.8, (this.levels.foxy / 20 + .12) * this.timePressure());
467:       if (Math.random() < chance) {
468:         f.stage++;
469:         f.timer = f.stage >= 3 ? 5.2 : 13.5;
470:         this.audio.servo(-.6);
471:         if (f.stage === 3) this.events.onFoxyReady?.();
472:       } else {
473:         f.timer = 6 + Math.random() * 5;
474:       }
475:     }
476:   }
