284: function setLook(dx, dy) {
285:   const sens = 0.0033;
286:   look.yaw = clamp(look.yaw - dx * sens, -1.52, 1.52);
287:   look.pitch = clamp(look.pitch - dy * 0.0025, -0.36, 0.28);
