// Screenshot helper: boots the game, walks to a state, saves a JPEG.
// usage: node shot.js <outfile> <state>   state: menu|office|cams|intro
const { chromium } = require('playwright-core');

(async () => {
  const [out, want] = process.argv.slice(2);
  const browser = await chromium.launch({
    executablePath: '/usr/bin/chromium',
    args: ['--no-sandbox', '--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader']
  });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  page.on('console', m => { if (m.type() === 'error') console.log('PAGE ERR:', m.text()); });
  page.on('pageerror', e => console.log('PAGE EXC:', e.message));
  await page.goto('http://localhost:8123/', { waitUntil: 'load' });
  await page.waitForTimeout(2500);
  const t0 = await page.evaluate(() => window.__fnf ? 'ready' : 'no __fnf');
  console.log('boot:', t0);
  const enter = await page.$('#boot-start');
  if (enter && await enter.isVisible()) { await enter.click(); await page.waitForTimeout(1200); }
  if (want === 'menu') { await snap(); return; }
  // start night 1
  await page.click('#start-night'); await page.waitForTimeout(900);
  if (want === 'intro') { await snap(); return; }
  await page.click('#intro-go'); await page.waitForTimeout(3000);
  if (want === 'cams') {
    await page.keyboard.press('Space'); await page.waitForTimeout(1500);
    await snap(); return;
  }
  if (want === 'later') {
    await page.waitForTimeout(30000); await snap(); return;
  }
  await snap();
  async function snap() {
    await page.screenshot({ path: out, type: 'jpeg', quality: 72 });
    console.log('saved', out);
  }
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

