// Screenshot every camera room by forcing the cam + fake game state.
const { chromium } = require('playwright-core');
(async () => {
  const out = process.argv[2] || '/tmp/opencode/rooms.jpg';
  const browser = await chromium.launch({
    executablePath: '/usr/bin/chromium',
    args: ['--no-sandbox', '--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader']
  });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  page.on('pageerror', e => console.log('EXC:', e.message));
  await page.goto('http://localhost:8123/', { waitUntil: 'load' });
  await page.waitForSelector('#boot-start:not(.hidden)', { timeout: 15000 });
  await page.click('#boot-start', { force: true });
  await page.waitForTimeout(400);
  await page.click('#start-night', { force: true });
  await page.click('#intro-go', { force: true });
  await page.waitForTimeout(1000);
  await page.keyboard.press('Space');
  await page.waitForTimeout(800);

  const cams = ['1A','1B','1C','2A','2B','3','4A','4B','5'];
  for (const c of cams) {
    await page.evaluate((id) => {
      const g = window.__fnf.game;
      g.nightT = 100; // 2:16 AM so AI may have moved
      // force AI into interesting positions for the shot
      g.ai.bonnie.index = 1; g.ai.chica.index = 1; g.ai.freddy.index = 1;
      g.foxy.stage = 1;
      window.__fnf.game.selectCam(id);
    }, c);
    await page.waitForTimeout(600);
  }
  // final: show last cam for the shot loop
  await page.evaluate(() => { window.__fnf.game.selectCam('1A'); });
  await page.waitForTimeout(500);
  await page.screenshot({ path: out.replace('.jpg', '_1a.jpg'), type: 'jpeg', quality: 72, clip: { x: 76, y: 72, width: 660, height: 372 } });
  const loop = cams.slice(1);
  for (const c of loop) {
    await page.evaluate(id => window.__fnf.game.selectCam(id), c);
    await page.waitForTimeout(700);
    await page.screenshot({ path: out.replace('.jpg', `_${c}.jpg`), type: 'jpeg', quality: 72, clip: { x: 76, y: 72, width: 660, height: 372 } });
  }
  console.log('done');
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

