167:   /* ============================================================ OFFICE */
168:   _buildOffice() {
169:     const s = this.scene;
170:     this.office = new THREE.Group();
171:     s.add(this.office);
172: 
173:     // materials — colour + generated tangent-space normals for crisp highlights
174:     const ns = (s) => new THREE.Vector2(s, s);
175:     const wall = new THREE.MeshStandardMaterial({
176:       map: wallTexture(), normalMap: normalTexture('plaster', 2.2), normalScale: ns(.72),
177:       roughness: .92, envMapIntensity: .24
178:     });
179:     const wains = new THREE.MeshStandardMaterial({
180:       map: wainscotTexture(), normalMap: normalTexture('wood', 2.0), normalScale: ns(.66),
181:       roughness: .8, envMapIntensity: .3
182:     });
183:     const ceil = new THREE.MeshStandardMaterial({
184:       map: ceilingTexture(), normalMap: normalTexture('tile', 1.4), normalScale: ns(.8),
185:       roughness: 1, envMapIntensity: .1
186:     });
187:     const floorM = new THREE.MeshStandardMaterial({
188:       map: floorTexture(), normalMap: normalTexture('tile', 1.8), normalScale: ns(.9),
189:       roughness: .3, metalness: .2, envMapIntensity: .8
190:     });
191:     const trim = new THREE.MeshStandardMaterial({
192:       color: 0x2a2118, normalMap: normalTexture('wood', 1.6), normalScale: ns(.5),
193:       roughness: .66, envMapIntensity: .22
194:     });
195:     const shutterM = new THREE.MeshStandardMaterial({
196:       map: shutterTexture(), normalMap: shutterNormalTexture(2.8), normalScale: ns(1),
197:       color: 0xe4e0d4, roughness: .44, metalness: .58, envMapIntensity: .9
198:     });
199: 
200:     // floor + ceiling
201:     const floor = plane(OFFICE.w * 2 + .4, OFFICE.back - OFFICE.front + .4, floorM, 0, 0, (OFFICE.back + OFFICE.front) / 2, -Math.PI / 2);
202:     floor.receiveShadow = true;
203:     this.office.add(floor);
204:     const ceiling = plane(OFFICE.w * 2 + .4, OFFICE.back - OFFICE.front + .4, ceil, 0, OFFICE.h, (OFFICE.back + OFFICE.front) / 2, Math.PI / 2);
205:     this.office.add(ceiling);
206: 
207:     // helper for wall section with upper paper + lower wainscot
208:     const buildWall = (w, wallH = OFFICE.h) => {
209:       const g = new THREE.Group();
210:       const lower = box(w, .92, .08, wains, 0, .46, 0);
211:       lower.receiveShadow = true;
212:       g.add(lower);
213:       const upperH = wallH - .92;
214:       const upper = plane(w, upperH, wall, 0, .92 + upperH / 2, .041);
215:       g.add(upper);
216:       const rail = box(w, .07, .13, trim, 0, .94, .04);
217:       g.add(rail);
218:       const base = box(w, .14, .1, trim, 0, .07, .04);
219:       g.add(base);
220:       return g;
221:     };
222: 
223:     // front wall (behind desk) at z = front
224:     const fw = buildWall(OFFICE.w * 2);
225:     fw.position.set(0, 0, OFFICE.front);
226:     this.office.add(fw);
227: 
228:     // back wall (behind player)
229:     const bw = buildWall(OFFICE.w * 2);
230:     bw.position.set(0, 0, OFFICE.back);
231:     bw.rotation.y = Math.PI;
232:     this.office.add(bw);
233: 
234:     // side walls with door openings
235:     const zA = OFFICE.front, zB = OFFICE.doorZ - OFFICE.doorW / 2;
236:     const zC = OFFICE.doorZ + OFFICE.doorW / 2, zD = OFFICE.back;
237:     const upperH = OFFICE.h - .92;
238:     for (const side of [-1, 1]) {
239:       const x = side * OFFICE.w;
240:       const ry = side < 0 ? Math.PI / 2 : -Math.PI / 2;
241:       const segs = [[zA, zB], [zC, zD]];
242:       for (const [za, zb] of segs) {
243:         const len = Math.abs(zb - za), cz = (za + zb) / 2;
244:         const lower = plane(len, .92, wains, x, .46, cz, 0, ry);
245:         lower.receiveShadow = true;
246:         const upper = plane(len, upperH, wall, x, .92 + upperH / 2, cz, 0, ry);
247:         upper.receiveShadow = true;
248:         this.office.add(lower, upper);
249:         this.office.add(box(.1, .07, len, trim, x, .945, cz));
250:         this.office.add(box(.1, .15, len, trim, x, .075, cz));
251:       }
252:       // header above the doorway
253:       const headerH = OFFICE.h - OFFICE.doorH;
254:       this.office.add(plane(OFFICE.doorW, headerH, wall, x, OFFICE.doorH + headerH / 2, OFFICE.doorZ, 0, ry));
255:       this.office.add(box(.1, .1, OFFICE.doorW + .2, trim, x, OFFICE.doorH + headerH - .05, OFFICE.doorZ));
256:     }
257: 
258:     // Door frames, steel shutters and the halls beyond them.
259:     for (const side of [-1, 1]) {
260:       const key = side < 0 ? 'left' : 'right';
261:       const doorX = side * OFFICE.w;
262:       const faceX = -side; // +1 points into the office
263:       const frameM = new THREE.MeshStandardMaterial({
264:         color: 0x3a3126, normalMap: normalTexture('metal', 1.8), normalScale: ns(.55),
265:         roughness: .46, metalness: .55, envMapIntensity: .55
266:       });
267:       const steelM = new THREE.MeshStandardMaterial({
268:         color: 0x777268, normalMap: normalTexture('metal', 2.2), normalScale: ns(.7),
269:         roughness: .36, metalness: .78, envMapIntensity: .95
270:       });
271:       const rubberM = mat({ color: 0x141210, roughness: .95 });
272: 
273:       // The opening runs along Z. Build the frame unrotated so the posts sit
274:       // on the wall rather than poking through it.
275:       const frame = new THREE.Group();
276:       frame.position.set(doorX, 0, OFFICE.doorZ);
277:       frame.add(box(.22, OFFICE.doorH + .12, .18, frameM, 0, (OFFICE.doorH + .12) / 2, -(OFFICE.doorW / 2 + .09)));
278:       frame.add(box(.22, OFFICE.doorH + .12, .18, frameM, 0, (OFFICE.doorH + .12) / 2, OFFICE.doorW / 2 + .09));
279:       frame.add(box(.22, .18, OFFICE.doorW + .36, frameM, 0, OFFICE.doorH + .09, 0));
280:       // bright inner lip catches the hall light
281:       frame.add(box(.06, OFFICE.doorH, .05, steelM, faceX * .09, OFFICE.doorH / 2, -(OFFICE.doorW / 2 + .015)));
282:       frame.add(box(.06, OFFICE.doorH, .05, steelM, faceX * .09, OFFICE.doorH / 2, OFFICE.doorW / 2 + .015));
283:       frame.add(box(.06, .05, OFFICE.doorW + .02, steelM, faceX * .09, OFFICE.doorH - .025, 0));
284:       // rubber bumpers
285:       frame.add(box(.035, OFFICE.doorH - .04, .035, rubberM, faceX * .08, OFFICE.doorH / 2, -(OFFICE.doorW / 2 - .032)));
286:       frame.add(box(.035, OFFICE.doorH - .04, .035, rubberM, faceX * .08, OFFICE.doorH / 2, OFFICE.doorW / 2 - .032));
287:       this.office.add(frame);
288: 
289:       // hazard threshold plate
290:       const hazardMat = new THREE.MeshStandardMaterial({ map: hazardTexture(), roughness: .82 });
291:       const threshold = plane(.16, OFFICE.doorW + .1, hazardMat, doorX + faceX * .02, .013, OFFICE.doorZ, -Math.PI / 2);
292:       this.office.add(threshold);
293:       const warning = plane(.42, .1, new THREE.MeshStandardMaterial({ map: hazardTexture(), roughness: .8 }), doorX + faceX * .045, OFFICE.doorH + .3, OFFICE.doorZ, 0, side < 0 ? Math.PI / 2 : -Math.PI / 2);
294:       this.office.add(warning);
295: 
296:       // Shutter — a single steel panel that slides straight up on Z-aligned rails.
297:       const sg = new THREE.Group();
298:       sg.position.set(doorX, 0, OFFICE.doorZ);
299:       this.office.add(sg);
300:       const shutter = box(.09, OFFICE.doorH + .06, OFFICE.doorW + .02, shutterM, faceX * .05, OFFICE.doorH / 2 + 2.4, 0);
301:       shutter.castShadow = true; shutter.receiveShadow = true;
302:       sg.add(shutter);
303:       for (const zs of [-1, 1]) {
304:         sg.add(box(.08, OFFICE.doorH + .16, .07, steelM, faceX * .105, OFFICE.doorH / 2, zs * (OFFICE.doorW / 2 + .045)));
305:       }
306:       // roller drum + housing above the opening
307:       sg.add(box(.34, .2, OFFICE.doorW + .3, frameM, faceX * .01, OFFICE.doorH + .21, 0));
308:       const drum = new THREE.Mesh(new THREE.CylinderGeometry(.1, .1, OFFICE.doorW + .17, 18), steelM);
309:       drum.rotation.x = Math.PI / 2;
310:       drum.position.set(faceX * .01, OFFICE.doorH + .19, 0);
311:       drum.castShadow = true;
312:       sg.add(drum);
313:       // warning light strip + halo on the roller housing
314:       const strip = box(.045, .035, OFFICE.doorW * .78, new THREE.MeshBasicMaterial({ color: 0x52140f, transparent: true, opacity: .9 }), faceX * .19, OFFICE.doorH + .2, 0);
315:       sg.add(strip);
316:       const stripGlow = this._glow(0xff3b26, .62, .01);
317:       stripGlow.position.set(faceX * .26, OFFICE.doorH + .2, 0);
318:       sg.add(stripGlow);
319: 
320:       // button panel (visual only)
321:       const panel = new THREE.Group();
322:       const pm = mat({ color: 0x2b2823, roughness: .6, metalness: .3 });
323:       panel.add(box(.05, .54, .3, pm, 0, 0, 0));
324:       const b1 = box(.03, .1, .11, mat({ color: 0xa8352c, emissive: 0x320704, emissiveIntensity: .5, roughness: .4 }), faceX * .04, .11, 0);
325:       const b2 = box(.03, .1, .11, mat({ color: 0xd0a04a, emissive: 0x2a1a02, emissiveIntensity: .4, roughness: .4 }), faceX * .04, -.11, 0);
326:       panel.add(b1, b2);
327:       panel.position.set(doorX + faceX * .17, 1.34, OFFICE.doorZ + .92);
328:       this.office.add(panel);
329:       this.doors = this.doors || {};
330:       this.doors[key] = { shutter, group: sg, strip, stripGlow, b1, b2, frame };
331: 
332:       // hall
333:       this._buildHall(side, key, floorM, wall, wains, trim, ceil);
334:     }
335: 
336:     // baseboards/ceiling strip
337:     this.office.add(box(OFFICE.w * 2, .08, .08, trim, 0, OFFICE.h - .04, OFFICE.front + .04));
338:     this.office.add(box(OFFICE.w * 2, .08, .08, trim, 0, OFFICE.h - .04, OFFICE.back - .04));
339: 
340:     this._buildLights();
341:     this._buildDesk();
342:     this._buildFrontWall();
343:     this._buildBackWall();
344:     this._buildDust();
345:     this._buildOfficeDetails();
346: 
347:     // ambient artificial light
348:     this.ambient = new THREE.HemisphereLight(0x8f7c5e, 0x17110c, .36);
349:     this.scene.add(this.ambient);
350:   }
