352:   _buildHall(side, key, floorM, wall, wains, trim, ceil) {
353:     const g = new THREE.Group();
354:     const len = 5.4;
355:     const width = 2.35;
356:     const hallX = side * (OFFICE.w + len / 2);
357:     const floor = plane(len, width, floorM, hallX, .001, OFFICE.doorZ, -Math.PI / 2);
358:     floor.receiveShadow = true;
359:     g.add(floor);
360:     g.add(plane(len, width, ceil, hallX, 2.62, OFFICE.doorZ, Math.PI / 2));
361:     // hallway side walls (parallel to x axis)
362:     for (const zs of [-1, 1]) {
363:       const wg = new THREE.Group();
364:       const lower = box(len, .85, .06, wains, 0, .425, 0);
365:       const upper = plane(len, 1.72, wall, 0, .85 + .86, .031);
366:       wg.add(lower, upper);
367:       wg.add(box(len, .06, .1, trim, 0, .86, .03));
368:       wg.position.set(hallX, 0, OFFICE.doorZ + zs * width / 2);
369:       if (zs < 0) wg.rotation.y = 0; else wg.rotation.y = Math.PI;
370:       g.add(wg);
371:     }
372:     // end wall
373:     const eg = new THREE.Group();
374:     eg.add(box(.08, 2.62, width, wall, 0, 1.31, 0));
375:     eg.position.set(side * (OFFICE.w + len), 0, OFFICE.doorZ);
376:     g.add(eg);
377:     // ceiling lamps
378:     const lampMat = new THREE.MeshBasicMaterial({ color: 0x312a1c });
379:     const lampGlows = [];
380:     for (const d of [1.3, 3.6]) {
381:       const lamp = box(.7, .04, .16, lampMat, side * (OFFICE.w + d), 2.56, OFFICE.doorZ);
382:       g.add(lamp);
383:       const glow = this._glow(0xffc98d, .95, .32);
384:       glow.position.set(side * (OFFICE.w + d), 2.5, OFFICE.doorZ);
385:       g.add(glow);
386:       lampGlows.push(glow);
387:     }
388:     this.doors[key].lampGlows = lampGlows;
389:     // shallow ceiling beams
390:     for (const d of [1.9, 2.9, 4.1]) {
391:       g.add(box(.08, .07, width, trim, side * (OFFICE.w + d), 2.585, OFFICE.doorZ));
392:     }
393:     // conduit running the length of the hall
394:     for (const zs of [-.92, .92]) {
395:       const pipe = new THREE.Mesh(new THREE.CylinderGeometry(.02, .02, len - .2, 6), new THREE.MeshStandardMaterial({ map: metalTexture(), roughness: .45, metalness: .7 }));
396:       pipe.rotation.z = Math.PI / 2;
397:       pipe.position.set(hallX, 2.5, OFFICE.doorZ + zs);
398:       g.add(pipe);
399:     }
400:     // fire alarm + staff door at the end
401:     const alarm = box(.13, .18, .07, mat({ color: 0xa8332a, roughness: .5 }), side * (OFFICE.w + 2.35), 1.95, OFFICE.doorZ + width / 2 - .08);
402:     g.add(alarm);
403:     const alarmGlow = this._glow(0xff4a32, .22, .5);
404:     alarmGlow.position.set(side * (OFFICE.w + 2.35), 1.98, OFFICE.doorZ + width / 2 - .12);
405:     g.add(alarmGlow);
406:     const endDoor = plane(1.02, 1.94, new THREE.MeshStandardMaterial({ map: metalTexture(), color: 0x8d8a80, roughness: .58, metalness: .42 }), side * (OFFICE.w + len - .05), .98, OFFICE.doorZ + .02, 0, side < 0 ? Math.PI / 2 : -Math.PI / 2);
407:     g.add(endDoor);
408:     g.add(box(1.16, .06, .05, trim, side * (OFFICE.w + len - .06), 1.99, OFFICE.doorZ + .02));
409:     g.add(box(1.12, .1, .05, trim, side * (OFFICE.w + len - .06), .05, OFFICE.doorZ + .02));
410:     const handle = new THREE.Mesh(new THREE.CylinderGeometry(.018, .018, .16, 6), new THREE.MeshStandardMaterial({ color: 0x9a9588, roughness: .3, metalness: .85 }));
411:     handle.rotation.z = Math.PI / 2;
412:     handle.position.set(side * (OFFICE.w + len - .13), 1.02, OFFICE.doorZ + .34);
413:     g.add(handle);
414:     const staffSign = plane(.42, .14, new THREE.MeshStandardMaterial({ map: signTexture(), roughness: .85 }), side * (OFFICE.w + len - .12), 1.65, OFFICE.doorZ + .34, 0, side < 0 ? Math.PI / 2 : -Math.PI / 2);
415:     g.add(staffSign);
416:     // hazard threshold at the office door
417:     const hazard = plane(.06, .7, new THREE.MeshStandardMaterial({ map: hazardTexture(), roughness: .8 }), side * (OFFICE.w + .28), .012, OFFICE.doorZ + width / 2 - .07, -Math.PI / 2);
418:     g.add(hazard);
419:     // low haze
420:     for (let i = 0; i < 3; i++) {
421:       const haze = this._glow(0xc9b18a, 1.5 + i * .6, .045);
422:       haze.position.set(side * (OFFICE.w + 1.2 + i * 1.6), .75 + i * .12, OFFICE.doorZ);
423:       g.add(haze);
424:     }
425:     // red EXIT sign just outside the office door
426:     const exitSign = plane(.34, .17, new THREE.MeshBasicMaterial({ map: exitTexture(), transparent: true }), side * (OFFICE.w + .06), 2.06, OFFICE.doorZ + 1.02);
427:     exitSign.rotation.y = side < 0 ? Math.PI / 2 : -Math.PI / 2;
428:     g.add(exitSign);
429:     const exitGlow = new THREE.PointLight(0xff2a18, 1.6, 3.4, 2);
430:     exitGlow.position.set(side * (OFFICE.w + .28), 2.0, OFFICE.doorZ + 1.02);
431:     g.add(exitGlow);
432:     // dim far-end practical light so the hall reads in the dark
433:     const farGlow = new THREE.PointLight(0x8d7a58, 1.1, 5.5, 2);
434:     farGlow.position.set(side * (OFFICE.w + len - .7), 2.35, OFFICE.doorZ);
435:     g.add(farGlow);
436: 
437:     // posters
438:     const posterSpots = [
439:       { kind: 'celebrate', d: 2.0, z: 0.55, s: .8 },
440:       { kind: 'safety', d: 3.6, z: -1.5, s: .7 },
441:       { kind: 'kids', d: 1.1, z: -1.7, s: .55 }
442:     ];
443:     for (const p of posterSpots) {
444:       const pm = new THREE.MeshStandardMaterial({ map: posterTexture(p.kind), roughness: .9 });
445:       const pl = plane(.62 * p.s / .62, .82 * p.s / .62, pm, side * (OFFICE.w + p.d), 1.5, OFFICE.doorZ + p.z * .7);
446:       pl.scale.set(p.s, p.s, 1);
447:       pl.rotation.y = side < 0 ? Math.PI / 2 : -Math.PI / 2;
448:       // Put against side wall instead
449:       pl.position.z = OFFICE.doorZ + (p.z > 0 ? width / 2 - .05 : -width / 2 + .05);
450:       pl.rotation.y = p.z > 0 ? Math.PI : 0;
451:       g.add(pl);
452:     }
453:     // floor scuffs and a "wet floor" cone
454:     const cone = new THREE.Mesh(
455:       new THREE.ConeGeometry(.18, .38, 14),
456:       mat({ color: 0xb99a32, roughness: .65 })
457:     );
458:     cone.position.set(side * (OFFICE.w + 1.6), .19, OFFICE.doorZ + .45);
459:     g.add(cone);
460:     this.scene.add(g);
461:     this.doors[key].hall = g;
462: 
463:     // door light source — mounted just inside the office, aimed into the hall
464:     const light = new THREE.SpotLight(0xffb56a, 0, 9, Math.PI / 4.2, .5, 1.5);
465:     light.position.set(side * (OFFICE.w + .22), 2.5, OFFICE.doorZ);
466:     light.target.position.set(side * (OFFICE.w + 3.4), .35, OFFICE.doorZ - .1);
467:     this.scene.add(light, light.target);
468:     light.castShadow = false;
469:     this.doors[key].light = light;
470:     this.doors[key].lightTarget = light.target;
471: 
472:     // Low fill on the office side so whoever is in the doorway reads clearly
473:     // when the hall light is switched on.
474:     const reveal = new THREE.PointLight(0xffc08a, 0, 3.8, 2);
475:     reveal.position.set(side * (OFFICE.w - .3), 1.78, OFFICE.doorZ + .52);
476:     this.scene.add(reveal);
477:     this.doors[key].revealLight = reveal;
478: 
479:     // fake volumetric cone — apex at the door, spreading down the hall
480:     const coneGeo = new THREE.ConeGeometry(1.5, 3.4, 18, 1, true);
481:     const coneMat = new THREE.MeshBasicMaterial({
482:       color: 0xffb060, transparent: true, opacity: 0, blending: THREE.AdditiveBlending,
483:       side: THREE.DoubleSide, depthWrite: false
484:     });
485:     const vol = new THREE.Mesh(coneGeo, coneMat);
486:     vol.rotation.set(0, 0, side * Math.PI / 2);
487:     vol.position.set(side * (OFFICE.w + 1.7), 1.55, OFFICE.doorZ);
488:     g.add(vol);
489:     this.doors[key].volume = vol;
490:     this.doors[key].volumeBase = coneMat;
491:   }
