521:     // warm glow strip on the ceiling around the panel
522:     this.office.add(box(1.9, .012, .84, new THREE.MeshBasicMaterial({ color: 0x3b2c1a }), 0, OFFICE.h - .008, .2));
523: 
524:     // desk monitor glow
525:     this.monitorLight = new THREE.PointLight(0x6fa98c, 1.8, 2.8, 2);
526:     this.monitorLight.position.set(1.05, 1.22, .45);
527:     this.office.add(this.monitorLight);
528: 
529:     // red door warning wash
530:     this.redWash = new THREE.PointLight(0xa3291f, .75, 4, 2);
