692: function syncWorldCharacters() {
693:   if (!game.ai) return;
694:   for (const side of ['left', 'right']) {
695:     const a = game.aiAtDoor(side);
696:     const type = a ? (a.name === 'freddy' ? 'freddy' : a.name) : null;
697:     if (cornerCache[side] !== type) {
698:       cornerCache[side] = type;
699:       world.setCornerCharacter(side, type);
700:     }
701:   }
702:   const f = game.foxy;
703:   const running = f.running;
704:   if (world._foxyRunning !== running) {
705:     world._foxyRunning = running;
706:     if (!running) world.setFoxyRunning(false);
707:   }
708:   if (running) world.setFoxyRunning(true, clamp(f.runT / 1.75, 0, 1));
