711: /* ------------------------------------------------------------------ loop */
712: function tick(now) {
713:   requestAnimationFrame(tick);
714:   let dt = (now - last) / 1000;
715:   last = now;
716:   if (dt > .1) dt = .1;
717:   if (dt <= 0) dt = .016;
718: 
719:   // keyboard look
720:   if (state === 'playing' && !game.camOpen) {
721:     let kx = 0, ky = 0;
722:     if (keys.has('arrowleft') || keys.has('a')) kx -= 1;
723:     if (keys.has('arrowright') || keys.has('d')) kx += 1;
724:     if (keys.has('arrowup') || keys.has('w')) ky -= 1;
725:     if (keys.has('arrowdown') || keys.has('s')) ky += 1;
726:     if (kx || ky) {
727:       look.yaw = clamp(look.yaw - kx * dt * 1.35, -1.52, 1.52);
728:       look.pitch = clamp(look.pitch - ky * dt * .75, -.32, .3);
729:       world.targetYaw = look.yaw;
730:       world.targetPitch = look.pitch;
731:     }
732:   }
733: 
734:   if (state === 'playing') {
735:     game.update(dt);
736:     updateHud();
737:     syncWorldCharacters();
738:     for (const side of ['left', 'right']) {
739:       world.setDoor(side, game.doors[side]);
740:       world.setLight(side, game.lights[side]);
741:     }
742:     world.setPower(game.power / 100);
743:     if (game.camOpen) {
744:       feed.draw(game, dt);
745:       feedAcc += dt;
746:       if (feedAcc > .2) {
747:         feedAcc = 0;
748:         setFeedClock();
749:       }
750:     }
751:   } else if (state === 'dead' || state === 'won') {
752:     world.setPower(game.power / 100);
753:   }
754: 
755:   world.update(dt);
756:   // while the tablet is up its own renderer drives the screen — skip the
757:   // office render to keep the two WebGL contexts light on phones.
758:   world.renderPaused = game.camOpen && state === 'playing';
759: 
760:   // adaptive quality for sustained mobile framerates
761:   fpsAcc += dt; fpsFrames++;
762:   if (fpsAcc > 2.2) {
763:     const fps = fpsFrames / fpsAcc;
764:     if (fps < 46 && quality > .62) {
765:       quality = Math.max(.62, quality - .11);
766:       world.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.75) * quality);
767:       goodWindows = 0;
768:     } else if (fps > 57 && quality < 1) {
769:       goodWindows++;
770:       if (goodWindows >= 3) {
771:         quality = Math.min(1, quality + .08);
772:         world.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.75) * quality);
773:         goodWindows = 0;
774:       }
775:     }
776:     fpsAcc = 0; fpsFrames = 0;
777:   }
778: }
