92: function partyTextTexture(word = "LET'S PARTY!") {
93:   const w = 512, h = 96, c = document.createElement('canvas');
94:   c.width = w; c.height = h;
95:   const x = c.getContext('2d');
96:   x.fillStyle = 'rgba(0,0,0,0)'; x.clearRect(0, 0, w, h);
97:   x.textAlign = 'center';
98:   x.font = 'bold 54px Georgia, serif';
99:   x.shadowColor = '#000'; x.shadowBlur = 6;
100:   x.fillStyle = '#e8d7ae';
101:   x.fillText(word, w / 2, 58);
