103:   x.fillStyle = 'rgba(232,215,174,.75)';
104:   x.fillText("FREDDY FAZBEAR'S PIZZA", w / 2, 86);
105:   const t = new THREE.CanvasTexture(c);
106:   t.colorSpace = THREE.SRGBColorSpace;
107:   return t;
108: }
