154:   /* small equirect gradient so floor tiles and metal get a believable sheen */
155:   _buildEnv() {
156:     const w = 512, h = 256, c = document.createElement('canvas');
157:     c.width = w; c.height = h;
158:     const x = c.getContext('2d');
159:     const g = x.createLinearGradient(0, 0, 0, h);
160:     g.addColorStop(0, '#0a0806');
161:     g.addColorStop(.42, '#4a3826');
162:     g.addColorStop(.6, '#6a5438');
163:     g.addColorStop(.8, '#221a12');
164:     g.addColorStop(1, '#070605');
165:     x.fillStyle = g; x.fillRect(0, 0, w, h);
166:     for (const sx of [128, 384]) {
167:       const rg = x.createRadialGradient(sx, 60, 2, sx, 60, 110);
168:       rg.addColorStop(0, 'rgba(255,226,176,.8)');
169:       rg.addColorStop(1, 'rgba(255,190,110,0)');
170:       x.fillStyle = rg; x.fillRect(sx - 110, 0, 220, 200);
171:     }
172:     const tex = new THREE.CanvasTexture(c);
173:     tex.mapping = THREE.EquirectangularReflectionMapping;
174:     tex.colorSpace = THREE.SRGBColorSpace;
175:     this.scene.environment = tex;
176:   }
