728:   _spareHead(type) {
729:     const palettes = {
730:       freddy: { main: 0x5a3a20, dark: 0x35200f, muzzle: 0xa87c4e },
731:       bonnie: { main: 0x4a3a78, dark: 0x2a2148, muzzle: 0x8d7cb0 },
732:       chica: { main: 0xcaa73f, dark: 0x8d7124, muzzle: 0xe0a83a },
733:       foxy: { main: 0x8c3323, dark: 0x542015, muzzle: 0xb26743 }
734:     };
735:     const p = palettes[type];
736:     const g = new THREE.Group();
737:     const mainM = new THREE.MeshStandardMaterial({ color: p.main, roughness: .8 });
738:     const muzzleM = new THREE.MeshStandardMaterial({ color: p.muzzle, roughness: .74 });
739:     const darkM = new THREE.MeshStandardMaterial({ color: 0x0c0906, roughness: .6 });
740:     const skull = new THREE.Mesh(new THREE.SphereGeometry(.2, 18, 14), mainM);
741:     skull.scale.set(1.06, .98, .94);
742:     g.add(skull);
743:     const muzzle = new THREE.Mesh(new THREE.SphereGeometry(.12, 14, 10), muzzleM);
744:     muzzle.scale.set(1.15, .78, 1.05);
745:     muzzle.position.set(0, -.06, .15);
746:     g.add(muzzle);
747:     for (const s of [-1, 1]) {
748:       const socket = new THREE.Mesh(new THREE.SphereGeometry(.052, 10, 8), darkM);
749:       socket.scale.set(1, .95, .55);
750:       socket.position.set(s * .08, .04, .15);
751:       g.add(socket);
752:       if (type === 'freddy') {
753:         const ear = new THREE.Mesh(new THREE.SphereGeometry(.07, 10, 8), mainM);
754:         ear.scale.set(1, 1, .5);
755:         ear.position.set(s * .15, .17, 0);
756:         g.add(ear);
757:       } else if (type === 'bonnie') {
758:         const ear = new THREE.Mesh(new THREE.CapsuleGeometry(.045, .2, 4, 8), mainM);
759:         ear.position.set(s * .09, .28, 0);
760:         ear.rotation.z = s * .12;
761:         g.add(ear);
762:       } else if (type === 'foxy') {
763:         const ear = new THREE.Mesh(new THREE.ConeGeometry(.055, .15, 4), mainM);
764:         ear.position.set(s * .12, .19, .01);
765:         ear.rotation.z = s * .18;
766:         g.add(ear);
767:       }
768:     }
769:     if (type === 'chica') {
770:       const beak = new THREE.Mesh(new THREE.ConeGeometry(.075, .12, 5), new THREE.MeshStandardMaterial({ color: 0xe08a2a, roughness: .52 }));
771:       beak.rotation.x = Math.PI / 2;
772:       beak.position.set(0, -.05, .24);
773:       g.add(beak);
774:     } else if (type === 'foxy') {
775:       const patch = new THREE.Mesh(new THREE.CircleGeometry(.055, 12), darkM);
776:       patch.position.set(-.08, .04, .165);
777:       g.add(patch);
778:     } else {
779:       const nose = new THREE.Mesh(new THREE.SphereGeometry(.035, 8, 6), new THREE.MeshStandardMaterial({ color: 0x16110c, roughness: .4 }));
780:       nose.scale.set(1.2, .8, 1);
781:       nose.position.set(0, -.03, .27);
782:       g.add(nose);
783:     }
784:     if (type === 'freddy') {
785:       const felt = new THREE.MeshStandardMaterial({ color: 0x111010, roughness: .72 });
786:       const brim = new THREE.Mesh(new THREE.CylinderGeometry(.16, .16, .02, 16), felt);
787:       const top = new THREE.Mesh(new THREE.CylinderGeometry(.1, .115, .2, 16), felt);
788:       brim.position.y = .2; top.position.y = .3;
789:       g.add(brim, top);
790:     }
791:     return g;
792:   }
