804:    the plaster, wood and steel catch the light on a high-DPI phone screen. */
805: function normalFromSource(src, strength, repeat) {
806:   const w = src.width, h = src.height;
807:   const read = canvas(w, h), rx = read.getContext('2d');
808:   rx.drawImage(src, 0, 0);
809:   const data = rx.getImageData(0, 0, w, h).data;
810:   const out = canvas(w, h), ox = out.getContext('2d');
811:   const img = ox.createImageData(w, h);
812:   const at = (xx, yy) => data[((((yy + h) % h) * w + ((xx + w) % w)) * 4)] / 255;
813:   for (let y = 0; y < h; y++) {
814:     for (let x = 0; x < w; x++) {
815:       const dx = (at(x + 1, y) - at(x - 1, y)) * strength;
816:       const dy = (at(x, y + 1) - at(x, y - 1)) * strength;
817:       let nx = -dx, ny = -dy, nz = 1;
818:       const l = Math.hypot(nx, ny, nz) || 1;
819:       nx /= l; ny /= l; nz /= l;
820:       const i = (y * w + x) * 4;
821:       img.data[i] = (nx * .5 + .5) * 255;
822:       img.data[i + 1] = (ny * .5 + .5) * 255;
823:       img.data[i + 2] = (nz * .5 + .5) * 255;
824:       img.data[i + 3] = 255;
825:     }
826:   }
827:   ox.putImageData(img, 0, 0);
828:   const t = new THREE.CanvasTexture(out);
829:   t.wrapS = t.wrapT = THREE.RepeatWrapping;
830:   if (repeat) t.repeat.copy(repeat);
831:   t.anisotropy = maxAnisotropy;
832:   t.colorSpace = THREE.NoColorSpace;
833:   return t;
